void parse_form_data(const char *data, char *name, char *message) {
    char *copy = strdup(data);
    char *token;
    char *saveptr;

    token = strtok_r(copy, "&", &saveptr);
    while (token) {
        char *eq = strchr(token, '=');
        if (eq) {
            *eq = '\0';
            char *key = token;
            char *value = eq + 1;
            char *decoded = url_decode(value);

            if (strcmp(key, "name") == 0) {
                strncpy(name, decoded, MAX_FIELD - 1);
                name[MAX_FIELD - 1] = '\0';
            } else if (strcmp(key, "message") == 0) {
                strncpy(message, decoded, MAX_FIELD - 1);
                message[MAX_FIELD - 1] = '\0';
            }
            free(decoded);
        }
        token = strtok_r(NULL, "&", &saveptr);
    }
    free(copy);
}

int main(void) {
    char *method = getenv("REQUEST_METHOD");
    char *query = getenv("QUERY_STRING");
    char *content_length_str = getenv("CONTENT_LENGTH");
    char input[MAX_INPUT] = {0};
    char name[MAX_FIELD] = {0};
    char message[MAX_FIELD] = {0};
    int submitted = 0;

    if (method && strcmp(method, "POST") == 0 && content_length_str) {
        int len = atoi(content_length_str);
        if (len > 0 && len < MAX_INPUT) {
            size_t read = fread(input, 1, len, stdin);
            input[read] = '\0';
        }
    } else if (method && strcmp(method, "GET") == 0 && query) {
        strncpy(input, query, MAX_INPUT - 1);
    }

    if (strlen(input) > 0) {
        parse_form_data(input, name, message);
        submitted = 1;
    }

    render_page(name, message, submitted);
    return 0;
}
